/**
 * Packs a macOS `.icns` from PNGs, for machines without `iconutil`.
 *
 *   node icns.mjs <iconset-dir> <out.icns>
 *
 * `generate.sh` uses `iconutil` on macOS and this everywhere else, so the
 * desktop icon is regenerated by the same command on any machine. The iconset
 * is `iconutil`'s layout (`icon_16x16.png`, `icon_16x16@2x.png`, ...), and the
 * chunks are the ones `iconutil` writes: PNG bodies, except 16 and 32 at 1x
 * (`ic04`, `ic05`), which `iconutil` stores as run-length ARGB and so does this.
 * Pixels come from ImageMagick, which `generate.sh` already needs.
 */
import { execFileSync } from "node:child_process";
import { readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const [dir, out] = process.argv.slice(2);
if (!dir || !out) {
  console.error("usage: node icns.mjs <iconset-dir> <out.icns>");
  process.exit(1);
}

const CHUNKS = [
  ["ic04", "icon_16x16.png"],
  ["ic11", "icon_16x16@2x.png"],
  ["ic05", "icon_32x32.png"],
  ["ic12", "icon_32x32@2x.png"],
  ["ic07", "icon_128x128.png"],
  ["ic13", "icon_128x128@2x.png"],
  ["ic08", "icon_256x256.png"],
  ["ic14", "icon_256x256@2x.png"],
  ["ic09", "icon_512x512.png"],
  ["ic10", "icon_512x512@2x.png"],
];

/** One channel in icns run-length form: runs of 3 to 130, literals of 1 to 128. */
function rle(bytes) {
  const out = [];
  let i = 0;
  while (i < bytes.length) {
    let run = 1;
    while (i + run < bytes.length && run < 130 && bytes[i + run] === bytes[i]) run++;
    if (run >= 3) {
      out.push(0x80 + run - 3, bytes[i]);
      i += run;
      continue;
    }
    const start = i;
    while (
      i < bytes.length &&
      i - start < 128 &&
      !(i + 2 < bytes.length && bytes[i] === bytes[i + 1] && bytes[i] === bytes[i + 2])
    )
      i++;
    out.push(i - start - 1, ...bytes.subarray(start, i));
  }
  return out;
}

/** `ARGB` followed by the alpha, red, green and blue planes, each run-length coded. */
function argb(file) {
  const rgba = execFileSync("magick", [file, "-depth", "8", "RGBA:-"]);
  const n = rgba.length / 4;
  const planes = [3, 0, 1, 2].map((c) => {
    const plane = new Uint8Array(n);
    for (let p = 0; p < n; p++) plane[p] = rgba[p * 4 + c];
    return rle(plane);
  });
  return Buffer.concat([Buffer.from("ARGB", "ascii"), Buffer.from(planes.flat())]);
}

const parts = CHUNKS.map(([type, file]) => {
  const path = join(dir, file);
  const data = type === "ic04" || type === "ic05" ? argb(path) : readFileSync(path);
  const head = Buffer.alloc(8);
  head.write(type, 0, "ascii");
  head.writeUInt32BE(data.length + 8, 4);
  return Buffer.concat([head, data]);
});
const body = Buffer.concat(parts);
const head = Buffer.alloc(8);
head.write("icns", 0, "ascii");
head.writeUInt32BE(body.length + 8, 4);
writeFileSync(out, Buffer.concat([head, body]));
console.log(`${CHUNKS.length}`);
